    let lagSX = 0, lagSY = 0, lagSZ = 0;
    let lagEX = 0, lagEY = 0, lagEZ = 0;
    let lagInit = false;

function renderGun() {
    const StartPosition = rightHandTransform.method("get_position").invoke();
    const Direction = rightHandTransform.method("get_forward").invoke();

    const rayStartPosition = Vector3.method("op_Addition").invoke(
        StartPosition,
        Vector3.method("op_Multiply").invoke(Direction, 0.08)
    );

    const layerMask = -1;
    let finalRay = null;
    let EndPosition;

    try {
        const hits = Physics.method("RaycastAll", 5).invoke(rayStartPosition, Direction, 100.0, layerMask, 2);
        if (hits && !hits.isNull() && hits.length > 0) {
            let bestDistance = Number.POSITIVE_INFINITY;
            for (let i = 0; i < hits.length; i++) {
                const hit = hits.get(i);
                if (!hit || hit.isNull?.()) continue;
                const hitPoint = hit.method("get_point").invoke();
                const distance = Vector3.method("Distance").invoke(hitPoint, StartPosition) as number;
                if (distance < 0.08 || distance >= bestDistance) continue;
                bestDistance = distance;
                finalRay = hit;
            }
        }
    } catch(_) {}

    if (finalRay) {
        EndPosition = finalRay.method("get_point").invoke();
    } else {
        EndPosition = Vector3.method("op_Addition").invoke(
            StartPosition,
            Vector3.method("op_Multiply").invoke(Direction, 50)
        );
    }

    if (GunPointer == null || GunPointer.isNull?.()) {
        GunPointer = createObject(EndPosition, identityQuaternion, [0.08, 0.08, 0.08], 0, [0, 0, 1, 1]);
        try { Destroy(getComponent(GunPointer, Collider)); } catch(_) {}
    }
    GunPointer.method("SetActive").invoke(true);
    getTransform(GunPointer).method("set_position").invoke(EndPosition);
    const pMat = getComponent(GunPointer, Renderer).method("get_material").invoke();
    pMat.method("set_shader").invoke(TextShader);
    
    pMat.method("set_color").invoke(rightTrigger ? [0, 0, 1, 1] : [0, 0.5, 1, 1]);

    if (GunLine == null || GunLine.isNull?.()) {
        const lineObj = createObject(zeroVector, identityQuaternion, oneVector, 0, [0, 0, 0, 0]);
        GunLine = addComponent(lineObj, LineRenderer);
    } else {
        GunLine.method("get_gameObject").invoke().method("SetActive").invoke(true);
    }
    const lineMat = GunLine.method("get_material").invoke();
    lineMat.method("set_shader").invoke(TextShader);
    
    GunLine.method("set_startColor").invoke([0, 0, 0, 1]);
    GunLine.method("set_endColor").invoke([0, 0, 0, 1]);
    GunLine.method("set_startWidth").invoke(0.02);
    GunLine.method("set_endWidth").invoke(0.02);
    GunLine.method("set_useWorldSpace").invoke(true);

    const segments = 10;
    GunLine.method("set_positionCount").invoke(segments + 1);

    GunLine.method("SetPosition").invoke(0, StartPosition);

    const upVector = Math.abs(Direction[1]) > 0.9 ? [0, 0, 1] : [0, 1, 0];
    const perpX = Vector3.method("Cross").invoke(Direction, upVector);
    const perpY = Vector3.method("Cross").invoke(Direction, perpX);

    const shakeIntensity = 0.15; 

    for (let i = 1; i < segments; i++) {
        const t = i / segments;
        
        const lerpedPos = Vector3.method("Lerp").invoke(StartPosition, EndPosition, t);
        
        const offsetFactorX = (Math.random() * 2 - 1) * shakeIntensity;
        const offsetFactorY = (Math.random() * 2 - 1) * shakeIntensity;
        
        const offsetX = Vector3.method("op_Multiply").invoke(perpX, offsetFactorX);
        const offsetY = Vector3.method("op_Multiply").invoke(perpY, offsetFactorY);
        const totalOffset = Vector3.method("op_Addition").invoke(offsetX, offsetY);
        
        const jaggedPos = Vector3.method("op_Addition").invoke(lerpedPos, totalOffset);
        
        GunLine.method("SetPosition").invoke(i, jaggedPos);
    }

    GunLine.method("SetPosition").invoke(segments, EndPosition);

    return { ray: finalRay, gunPointer: GunPointer, endPosition: EndPosition };
}

function recenterMenu() {
        const menuTransform = getTransform(menu);
        let targetPos, targetRot;

        if (righthand) {
            targetPos = rightHandTransform.method("get_position").invoke();
            targetRot = rightHandTransform.method("get_rotation").invoke();
            targetRot = Quaternion.method("op_Multiply").invoke(targetRot, Quaternion.method("Euler").invoke(0, 0, 180));
        } else {
            targetPos = leftHandTransform.method("get_position").invoke();
            targetRot = leftHandTransform.method("get_rotation").invoke();
            targetRot = Quaternion.method("op_Multiply").invoke(targetRot, Quaternion.method("Euler").invoke(0, 0, 0));
        }

        if (LerpMenu) {
            const menuPos = menuTransform.method("get_position").invoke();
            const distance = Vector3.method("Distance").invoke(menuPos, zeroVector);
            if (distance < 1) {
                menuTransform.method("set_position").invoke(targetPos);
                menuTransform.method("set_rotation").invoke(targetRot);
            } else {
                const newPos = Vector3.method("Lerp").invoke(menuPos, targetPos, deltaTime * 15);
                menuTransform.method("set_position").invoke(newPos);
                const newRot = Quaternion.method("Slerp").invoke(menuTransform.method("get_rotation").invoke(), targetRot, deltaTime * 15);
                menuTransform.method("set_rotation").invoke(newRot);
            }
        } else {
            menuTransform.method("set_position").invoke(targetPos);
            menuTransform.method("set_rotation").invoke(targetRot);
        }
    }
    
    let beforeSpawnDelegate = null;
    let beforeSpawnDelegateClass = null;
    let validatorBypassEnabled = false;

    function enableMobValidatorBypass() {
        if (validatorBypassEnabled) return;

        Il2Cpp.domain
            .assembly("AnimalCompany")
            .image.class("AnimalCompany.MobSpawnValidator")
            .method("IsMobAllowed", 1)
            .implementation = () => true;

        validatorBypassEnabled = true;
    }

    function getBeforeMobSpawnDelegate() {
        if (beforeSpawnDelegate) return beforeSpawnDelegate;

        beforeSpawnDelegateClass = Il2Cpp.domain
            .assembly("Fusion.Runtime")
            .image.class("Fusion.NetworkRunner")
            .tryNested("OnBeforeSpawned");

        const validator = Il2Cpp.domain
            .assembly("AnimalCompany")
            .image.class("AnimalCompany.MobSpawnValidator");

        beforeSpawnDelegate = Il2Cpp.delegate(
            beforeSpawnDelegateClass,
            (_runner, networkObject) => {
                if (!networkObject || networkObject.handle?.isNull()) return;

                const networkId = networkObject.method("get_Id").invoke();
                validator.method("AddAllowMob", 1).invoke(networkId);
            }
        );

        return beforeSpawnDelegate;
    }

    function spawnMob(mobName, position, rotation = identityQuaternion) {
        enableMobValidatorBypass();

        const animalCompany = Il2Cpp.domain.assembly("AnimalCompany").image;
        const prefabGenerator = animalCompany.class("AnimalCompany.PrefabGenerator");
        const mobIdClass = animalCompany.class("AnimalCompany.MobID");

        const cleanName = String(mobName).replace(/^mob_prefab\//, "");
        const candidates = [
            cleanName,
            cleanName.replace(/Controller$/, ""),
            cleanName.replace(/_?Controller$/, "")
        ];

        let mobId = null;

        for (const candidate of candidates) {
            try {
                mobId = mobIdClass.field(candidate).value;
                break;
            } catch {}
        }

        if (mobId === null) return false;

        prefabGenerator.method("SpawnMobAsync", 6).overload(
            "AnimalCompany.MobID",
            "UnityEngine.Vector3",
            "UnityEngine.Quaternion",
            "Fusion.NetworkRunner.OnBeforeSpawned",
            "Fusion.NetworkObjectSpawnDelegate",
            "System.String"
        ).invoke(
            mobId,
            position,
            rotation,
            getBeforeMobSpawnDelegate(),
            objectReference,
            Il2Cpp.string("mod")
        );

        return true;
    }

    function spawnNetworkPrefab(prefabName, pos, rot) {
        try {
            const runner = PrefabGen.field("_instance")
                .value.method("get_runner")
                .invoke();
            if (!runner || runner.isNull())
                return null;
            const sources = runner
                .field("_config")
                .value.field("PrefabTable")
                .value.field("_sources").value;
            const count = sources.method("get_Count").invoke();
            for (let i = 0; i < count; i++) {
                try {
                    const source = sources.method("get_Item").invoke(i);
                    const desc = source
                        .method("get_Description")
                        .invoke()
                        .toString();
                    if (desc.includes(prefabName)) {
                        const no = source.method("WaitForResult").invoke();
                        if (!no || no.isNull())
                            return null;
                        const makeZeroForType = type => {
                            if (type.class.isEnum || type.isPrimitive)
                                return 0;
                            if (!type.class.isValueType)
                                return NULL;
                            const fields = type.class.fields.filter(f => !f.isStatic);
                            if (fields.length === 0)
                                return 0;
                            return fields.map(f => makeZeroForType(f.type));
                        };
                        const buildNullableArg = (nullableType, hasValue, value) => {
                            const fields = nullableType.class.fields.filter(f => !f.isStatic);
                            return fields.map(f => {
                                const lname = f.name.toLowerCase();
                                if (lname.includes("hasvalue"))
                                    return hasValue ? 1 : 0;
                                if (lname === "value")
                                    return hasValue ? value : makeZeroForType(f.type);
                                return makeZeroForType(f.type);
                            });
                        };
                        const normalizeValue = (type, value) => {
                            if (typeof value === "boolean")
                                return value ? 1 : 0;
                            if (value instanceof Il2Cpp.ValueType) {
                                const fields = type.class.fields.filter(f => !f.isStatic);
                                if (fields.length === 0)
                                    return 0;
                                return fields.map(f => normalizeValue(f.type, f.bind(value).value));
                            }
                            if (Array.isArray(value))
                                return value.map(v => normalizeValue(type, v));
                            return value;
                        };
                        const buildNullableFromValueType = (nullableType, valueType) => {
                            return buildNullableArg(nullableType, true, normalizeValue(valueType.type, valueType));
                        };
                        let spawnMethod = null;
                        for (const m of runner.method("Spawn").overloads()) {
                            if (m.parameterCount !== 6 || m.isGeneric)
                                continue;
                            const p = m.parameters;
                            if (p[0].type.name.includes("Fusion.NetworkObject") &&
                                p[1].type.name.startsWith("System.Nullable") &&
                                p[1].type.name.includes("Vector3") &&
                                p[2].type.name.startsWith("System.Nullable") &&
                                p[2].type.name.includes("Quaternion") &&
                                p[3].type.name.startsWith("System.Nullable") &&
                                p[3].type.name.includes("PlayerRef") &&
                                p[4].type.name.includes("OnBeforeSpawned") &&
                                p[5].type.name.includes("NetworkSpawnFlags")) {
                                spawnMethod = m;
                                break;
                            }
                        }
                        if (!spawnMethod)
                            return null;
                        const posArg = buildNullableFromValueType(spawnMethod.parameters[1].type, pos);
                        const rotArg = buildNullableFromValueType(spawnMethod.parameters[2].type, rot);
                        const authArg = buildNullableArg(spawnMethod.parameters[3].type, false, makeZeroForType(spawnMethod.parameters[3].type));
                        const onBeforeArg = spawnMethod.parameters[4].type.class.isValueType ?
                            makeZeroForType(spawnMethod.parameters[4].type) :
                            NULL;
                        return spawnMethod
                            .bind(runner)
                            .invoke(no, posArg, rotArg, authArg, onBeforeArg, 0);
                    }
                } catch (_) {}
            }
        } catch (e) {
            console.error("spawnNetworkPrefab error:", e);
        }
        return null;
    }

